@startuml

class Song {
  + title : string
  + year : int
  + length : time
  + genre : string
}

class Artist {
  + name : string
  + birthDate : date
  + website : string
}

class User {
  + ID : int
  + name : string
  + address : string
}

abstract class UserType {
  + VATNumber : string
}

class RegularUser {}
class BusinessUser {}

class Album {
  + title : string
  + trackNumber : int
}

class Single {}

RegularUser --|> User
BusinessUser --|> User
BusinessUser "1" -- "*" Song
Song "1" -- "1" Artist
Single "1" -- "1" Song
RegularUser "0..*" -- "1..*" Album
Album "0..*" -- "1" Single

@enduml

